// Purpose: Validate Reviewed Artifact Reference. Keep this deterministic and fail closed.
const request = $json;
if (!request.artifact_id || !/^[a-f0-9]{64}$/i.test(String(request.expected_sha256 || ''))) {
    throw new Error('artifact_id and expected_sha256 are required');
}
const forbidden = ['provider', 'path', 'url', 'binary', 'capture_schema', 'review_status'];
if (forbidden.some(field => Object.hasOwn(request, field))) {
    throw new Error('Artifact metadata must be resolved from durable server state');
}
return [{ json: { artifact_id: String(request.artifact_id), expected_sha256: String(request.expected_sha256).toLowerCase() } }];

// Purpose: Verify Durable Artifact Contract. Keep this deterministic and fail closed.
const expected = $('Validate Reviewed Artifact Reference').first().json;
const record = $('Load Durable Document Record').first().json;
const observed = String($json.reviewed_sha256 || '').toLowerCase();
if (!record.document_id || !record.onedrive_item_id) {
    throw new Error('DURABLE_ARTIFACT_RECORD_MISSING');
}
if (record.source_sha256 !== expected.expected_sha256 || observed !== expected.expected_sha256) {
    throw new Error('REVIEWED_ARTIFACT_HASH_MISMATCH');
}
if (record.document_profile === 'STATEMENT_PDF_V1') {
    const required = [
        'source_code',
        'config_version',
        'actual_file_id',
        'account_id',
        'period_key',
        'source_message_id',
        'source_attachment_id',
    ];
    for (const field of required) {
        if (!record[field]) {
            throw new Error(`DURABLE_STATEMENT_CONTEXT_MISSING:${field}`);
        }
    }
    if (record.state !== 'READY_FOR_PARSE') {
        throw new Error(`DURABLE_STATEMENT_NOT_READY:${record.state || 'MISSING'}`);
    }
}
return [{
        json: {
            ...record,
            run_id: `reviewed:${record.document_id}`,
            trigger_kind: 'SUBWORKFLOW',
            message_id: record.source_message_id,
            attachment_id: record.source_attachment_id,
            document_sha256: observed,
        },
        binary: $binary,
    }];

// Purpose: Validate the redacted headed-browser contract before headless processing.
const capture = $json;
const record = $('Verify Durable Artifact Contract').first().json;
if (capture.schema_version !== 1 || !capture.capture_id || !capture.source || !capture.artifact || !capture.account) {
    throw new Error('BROWSER_CAPTURE_SCHEMA_INVALID');
}
const contract = capture.capture_contract;
if (!contract || contract.capture_mode !== 'HEADED_ON_DEMAND' || contract.redaction !== 'REDACTED' || contract.immutability !== 'SHA256_ARCHIVED' || contract.handoff_workflow !== 'INTERACTIVE_ARTIFACT_HANDOFF' || contract.actual_mutation !== false || contract.cashback_mutation !== false) {
    throw new Error('BROWSER_CAPTURE_CONTRACT_INVALID');
}
const forbidden = new Set(['access_token', 'authorization', 'cookie', 'cookies', 'credential', 'credentials', 'cvv', 'full_account_number', 'full_card_number', 'mfa_code', 'otp', 'password', 'passcode', 'pin', 'recovery_code', 'session', 'session_state', 'session_storage', 'token', 'username']);
const inspect = (value) => {
    if (Array.isArray(value)) {
        value.forEach(inspect);
        return;
    }
    if (!value || typeof value !== 'object')
        return;
    for (const [key, child] of Object.entries(value)) {
        if (forbidden.has(String(key).toLowerCase().replaceAll('-', '_')))
            throw new Error(`BROWSER_CAPTURE_FORBIDDEN_FIELD:${String(key)}`);
        inspect(child);
    }
};
inspect(capture);
return [{ json: { handoff_status: 'READY_FOR_HEADLESS', capture_id: String(capture.capture_id), provider: String(capture.source.provider), artifact_kind: String(capture.artifact.kind), source_sha256: String(record.source_sha256), source_code: String(record.source_code), headless_owner: 'N8N', actual_mutation: false, cashback_mutation: false, next_stages: ['VALIDATE', 'ENRICH', 'MATCH', 'ARCHIVE', 'ACTUAL_OUTBOX_REVIEW'] }, binary: $binary }];
